    Transforms the input grid according to the discovered rule:
    - Identify each orthogonal connected component of 1's that forms a rectangular frame
      (i.e. its bounding box has at least 3 rows and 3 columns).
    - For each such frame:
        * Fill any missing border cells that are aligned with the interior
          (top/bottom sides for columns inside the interior, left/right sides for rows
          inside the interior) with 1.
        * Count the interior cells that are zero in the original grid.
          If this number is odd, fill those cells with 7, otherwise fill them with 2.
    The rest of the grid (including other 1's and all 0's) stays unchanged.
    """
    if not grid:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # output starts as a copy of the input
    out = [row[:] for row in grid]

    visited = [[False] * cols for _ in range(rows)]
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and not visited[r][c]:
                # ---- collect the component ----
                stack = [(r, c)]
                visited[r][c] = True
                component = []
                min_r = max_r = r
                min_c = max_c = c

                while stack:
                    cr, cc = stack.pop()
                    component.append((cr, cc))
                    if cr < min_r:
                        min_r = cr
                    if cr > max_r:
                        max_r = cr
                    if cc < min_c:
                        min_c = cc
                    if cc > max_c:
                        max_c = cc
                    for dr, dc in dirs:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not visited[nr][nc] and grid[nr][nc] == 1:
                                visited[nr][nc] = True
                                stack.append((nr, nc))

                # ---- decide whether it is a rectangular frame ----
                height = max_r - min_r + 1
                width = max_c - min_c + 1
                if height < 3 or width < 3:
                    continue  # cannot contain an interior

                interior_r_start = min_r + 1
                interior_r_end = max_r - 1
                interior_c_start = min_c + 1
                interior_c_end = max_c - 1

                # collect interior zero cells (those that are zero in the original grid)
                interior_zeros = []
                for ir in range(interior_r_start, interior_r_end + 1):
                    for ic in range(interior_c_start, interior_c_end + 1):
                        if grid[ir][ic] == 0:
                            interior_zeros.append((ir, ic))

                if not interior_zeros:
                    # nothing to fill inside, but we still may need to complete the border
