                    # which sides need to be completed?
                    need_top = any(ir == interior_r_start for ir, _ in interior_zeros)
                    need_bottom = any(ir == interior_r_end for ir, _ in interior_zeros)
                    need_left = any(ic == interior_c_start for _, ic in interior_zeros)
                    need_right = any(ic == interior_c_end for _, ic in interior_zeros)

                    # fill missing border cells on needed sides
                    if need_top:
                        for ic in range(interior_c_start, interior_c_end + 1):
                            if out[min_r][ic] == 0:
                                out[min_r][ic] = 1
                    if need_bottom:
                        for ic in range(interior_c_start, interior_c_end + 1):
                            if out[max_r][ic] == 0:
                                out[max_r][ic] = 1
                    if need_left:
                        for ir in range(interior_r_start, interior_r_end + 1):
                            if out[ir][min_c] == 0:
                                out[ir][min_c] = 1
                    if need_right:
                        for ir in range(interior_r_start, interior_r_end + 1):
                            if out[ir][max_c] == 0:
                                out[ir][max_c] = 1

                    # fill interior zeros
                    fill_val = 7 if (len(interior_zeros) % 2 == 1) else 2
                    for ir, ic in interior_zeros:
